"""Answer parsing copied from the selected baseline."""

import json
import re


def extract_json_field(text: str, field: str, default: str = "") -> str:
    """Helper function to extract a field from JSON in LLM response."""
    # Try direct parse
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            return str(data.get(field, default))
    except json.JSONDecodeError:
        pass

    # Try code blocks: ```json ... ``` or ``` ... ```
    for match in re.finditer(r"```(?:json)?\s*([\s\S]*?)\s*```", text):
        try:
            data = json.loads(match.group(1))
            if isinstance(data, dict):
                return str(data.get(field, default))
        except json.JSONDecodeError:
            pass

    # Find balanced braces and try parsing
    for start in range(len(text)):
        if text[start] != "{":
            continue
        depth, pos, in_str = 1, start + 1, False
        while pos < len(text) and depth > 0:
            c = text[pos]
            if c == '"' and (pos == 0 or text[pos - 1] != "\\"):
                in_str = not in_str
            elif not in_str:
                depth += 1 if c == "{" else (-1 if c == "}" else 0)
            pos += 1
        if depth == 0:
            candidate = text[start:pos]
            candidate = re.sub(
                r",\s*([\]}])", r"\1", candidate
            )  # Remove trailing commas
            try:
                data = json.loads(candidate)
                if isinstance(data, dict):
                    return str(data.get(field, default))
            except json.JSONDecodeError:
                pass

    # Regex fallback
    match = re.findall(rf'"{field}"\s*:\s*"([^"]*)"', text)
    return match[-1] if match else default

"""Evaluators for kept MCE and OOD tasks."""

from __future__ import annotations

import json
import re
from collections.abc import Callable

from .constants import TRANSFER_TASKS


def extract_final_answer(response_text: str) -> str:
    if not response_text:
        return ""

    text = response_text.strip()
    if text.startswith("```"):
        lines = text.splitlines()
        payload = []
        in_json = False
        for line in lines:
            stripped = line.strip()
            if stripped.startswith("```json"):
                in_json = True
                continue
            if stripped.startswith("```") and in_json:
                break
            if in_json:
                payload.append(line)
        if payload:
            text = "\n".join(payload)
        elif "```" in text:
            parts = text.split("```")
            if len(parts) >= 3:
                text = parts[1]
                if text.startswith("json"):
                    text = text[4:].strip()

    try:
        data = json.loads(text)
        if isinstance(data, dict) and "final_answer" in data:
            return str(data["final_answer"])
    except json.JSONDecodeError:
        pass

    match = re.search(r"\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}", text)
    if match:
        try:
            data = json.loads(match.group())
            if isinstance(data, dict) and "final_answer" in data:
                return str(data["final_answer"])
        except json.JSONDecodeError:
            pass

    return response_text


def eval_finer(prediction: str, target: str) -> bool:
    return extract_final_answer(prediction).lower().strip() == target.lower().strip()


def eval_uspto(prediction: str, target: str) -> dict:
    def parse_reactants(smiles: str) -> set[str]:
        return {
            part.strip().lower() for part in smiles.strip().split(".") if part.strip()
        }

    pred_set = parse_reactants(extract_final_answer(prediction))
    target_set = parse_reactants(target)
    if not pred_set and not target_set:
        jaccard = 1.0
    elif not pred_set or not target_set:
        jaccard = 0.0
    else:
        jaccard = len(pred_set & target_set) / len(pred_set | target_set)
    return {"correct": pred_set == target_set, "jaccard_similarity": jaccard}


def eval_symptom2disease(prediction: str, target: str) -> bool:
    text = extract_final_answer(prediction)
    match = re.search(r"\[DIAGNOSIS\](.*?)\[/DIAGNOSIS\]", text, re.I | re.S)
    if match:
        text = match.group(1).strip()
    else:
        match = re.search(
            r"(?:diagnosis|final diagnosis|conclusion)[:：]\s*([^\n]+)", text, re.I
        )
        if match:
            text = match.group(1).strip()

    def normalize(value: str) -> str:
        value = value.lower().strip()
        value = re.sub(r"\s+", " ", value)
        return re.sub(r"[.!?]+$", "", value)

    return normalize(text) == normalize(target)


def eval_lawbench(prediction: str, target: str) -> dict:
    def parse_charges(text: str) -> set[str]:
        text = extract_final_answer(text).strip()
        match = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
        if match:
            text = match.group(1).strip()
        elif "罪名:" in text:
            text = text.split("罪名:")[-1]
        text = re.sub(r"<eoa>.*", "", text).strip()
        for sep in [";", "；", ",", "，", "、"]:
            if sep in text:
                return {part.strip() for part in text.split(sep) if part.strip()}
        return {text} if text else set()

    pred_charges = parse_charges(prediction)
    true_charges = parse_charges(target)
    tp = len(pred_charges & true_charges)
    fp = len(pred_charges - true_charges)
    fn = len(true_charges - pred_charges)
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return {
        "correct": pred_charges == true_charges,
        "f1": f1,
        "precision": precision,
        "recall": recall,
        "tp": tp,
        "fp": fp,
        "fn": fn,
    }


def eval_aegis(prediction: str, target: str) -> bool:
    pred = extract_final_answer(prediction).lower()
    if "unsafe" in pred:
        pred = "unsafe"
    elif "safe" in pred:
        pred = "safe"
    else:
        pred = pred.strip()
    return pred == target.lower().strip()


def eval_classification(prediction: str, target: str) -> bool:
    def normalize(text: str) -> str:
        text = extract_final_answer(text).lower().strip()
        text = text.replace("_", " ")
        text = re.sub(r"\s+", " ", text)
        return re.sub(r"[.!?]+$", "", text)

    return normalize(prediction) == normalize(target)


def get_evaluator(task: str) -> Callable:
    if task == "FiNER":
        return lambda pred, target, **kwargs: eval_finer(pred, target)
    if task == "USPTO":

        def _eval_uspto(pred: str, target: str, **kwargs) -> dict:
            raw = eval_uspto(pred, target)
            return {
                "was_correct": raw["correct"],
                "metrics": {"jaccard_similarity": raw["jaccard_similarity"]},
            }

        return _eval_uspto
    if task == "Symptom2Disease":
        return lambda pred, target, **kwargs: eval_symptom2disease(pred, target)
    if task == "LawBench":

        def _eval_lawbench(pred: str, target: str, **kwargs) -> dict:
            raw = eval_lawbench(pred, target)
            return {
                "was_correct": raw["correct"],
                "metrics": {
                    "f1": raw["f1"],
                    "precision": raw["precision"],
                    "recall": raw["recall"],
                    "tp": raw["tp"],
                    "fp": raw["fp"],
                    "fn": raw["fn"],
                },
            }

        return _eval_lawbench
    if task == "AEGIS":
        return lambda pred, target, **kwargs: eval_aegis(pred, target)
    if task in TRANSFER_TASKS:
        return lambda pred, target, **kwargs: eval_classification(pred, target)
    raise ValueError(f"Unknown task: {task}")

"""Answer-space index derived from the frozen memory.

The memory holds question/answer examples, so the answer strings it stores are
the only evidence the harness has about how this task spells its answers.  An
answer written by the model from its own knowledge drifts off that spelling by
a character (an extra or missing affix), which the benchmark scores as wrong
even when the meaning is right.  This module exposes the stored spellings so
the harness can ground the answer it returns.
"""

import json
from pathlib import Path

MEMORY_PATH = "/harness/memory/memory.json"
# Punctuation that joins several answer values inside one stored answer.
VALUE_SEPARATORS = (";", "；", ",", "，", "、", "|", "/")
MIN_VALUE_CHARS = 2
# Upper bound on the rendered list of stored spellings, so a memory with a huge
# answer space cannot crowd the rest of the prompt out.
MAX_VOCABULARY_CHARS = 6000


def components(answer: str) -> list[str]:
    """Split a stored answer into the values it is made of."""
    for separator in VALUE_SEPARATORS:
        if separator in answer:
            return [part.strip() for part in answer.split(separator) if part.strip()]
    return [answer.strip()] if answer.strip() else []


def _usable(value: str) -> bool:
    """False for values that are too short or could not be substituted into a response."""
    return len(value) >= MIN_VALUE_CHARS and '"' not in value and "\\" not in value


def _answers(memory_path: str) -> list[str]:
    """The answer each stored example carries, in memory order."""
    examples = json.loads(Path(memory_path).read_text())["examples"]
    return [str(example["target"]).strip() for example in examples]


def stored_answers(memory_path: str = MEMORY_PATH) -> list[str]:
    """The whole answers the memory stores, in memory order, without repeats."""
    ordered: list[str] = []
    seen: set[str] = set()
    for answer in _answers(memory_path):
        if _usable(answer) and answer not in seen:
            seen.add(answer)
            ordered.append(answer)
    return ordered


def stored_values(memory_path: str = MEMORY_PATH) -> list[str]:
    """Every spelling the memory stores: whole answers first, then their values.

    Order follows the memory, so the rendering is deterministic.
    """
    ordered: list[str] = []
    seen: set[str] = set()
    for answer in _answers(memory_path):
        for value in [answer, *components(answer)]:
            if _usable(value) and value not in seen:
                seen.add(value)
                ordered.append(value)
    return ordered


def vocabulary(
    memory_path: str = MEMORY_PATH,
    max_chars: int = MAX_VOCABULARY_CHARS,
) -> str:
    """Render the memory's whole stored answers as one newline-separated list."""
    lines: list[str] = []
    total = 0
    for answer in stored_answers(memory_path):
        if total + len(answer) + 1 > max_chars:
            break
        lines.append(answer)
        total += len(answer) + 1
    return "\n".join(lines)


def build_index(
    memory_path: str = MEMORY_PATH,
) -> tuple[frozenset[str], frozenset[str]]:
    """Return the answers the memory spells and the characters they are made of.

    Whole stored answers and their components count as spelled answers; the
    character set says what counts as answer content instead of formatting
    around it.
    """
    values = frozenset(stored_values(memory_path))
    alphabet = {character for value in values for character in value}
    return values, frozenset(alphabet)


def _is_boundary(text: str, position: int, alphabet: frozenset[str]) -> bool:
    """True where an answer value begins or ends instead of continuing."""
    if position < 0 or position >= len(text):
        return True
    character = text[position]
    return character not in alphabet or character in VALUE_SEPARATORS


def _occurrences(text: str, value: str) -> list[int]:
    positions = []
    start = text.find(value)
    while start != -1:
        positions.append(start)
        start = text.find(value, start + 1)
    return positions


def _is_spelled_out(
    text: str, value: str, positions: list[int], alphabet: frozenset[str]
) -> bool:
    """True if the text already uses the value as an answer, not as a fragment."""
    length = len(value)
    return any(
        _is_boundary(text, start - 1, alphabet)
        and _is_boundary(text, start + length, alphabet)
        for start in positions
    )


def canonicalize(
    text: str, index: tuple[frozenset[str], frozenset[str]]
) -> tuple[str, int]:
    """Spell answer values the way the memory spells them.

    A value the text already spells out is left alone.  Otherwise, an
    occurrence that becomes a stored value by dropping one character in front
    of or behind it is rewritten to that stored spelling, provided exactly one
    stored value claims the spot; anything else (a different value, an
    ambiguous match, an edit inside the value) is kept as written.
    """
    values, alphabet = index
    claims: dict[int, list[tuple[int, str]]] = {}
    for value in values:
        length = len(value)
        positions = _occurrences(text, value)
        if not positions or _is_spelled_out(text, value, positions, alphabet):
            continue
        for start in positions:
            for candidate_start, candidate_end in (
                (start - 1, start + length),
                (start, start + length + 1),
            ):
                if candidate_start < 0 or candidate_end > len(text):
                    continue
                if text[candidate_start:candidate_end] in values:
                    continue
                if not (
                    _is_boundary(text, candidate_start - 1, alphabet)
                    and _is_boundary(text, candidate_end, alphabet)
                ):
                    continue
                claims.setdefault(candidate_start, []).append(
                    (candidate_end - candidate_start, value)
                )
    replacements = sorted(
        (start, claim[0]) for start, claim in claims.items() if len(claim) == 1
    )
    parts = []
    cursor = 0
    applied = 0
    for start, (length, value) in replacements:
        if start < cursor:
            continue
        parts.append(text[cursor:start])
        parts.append(value)
        cursor = start + length
        applied += 1
    if not applied:
        return text, 0
    parts.append(text[cursor:])
    return "".join(parts), applied

